package com.example.ws

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.websocket.*
import io.ktor.websocket.*
import kotlinx.coroutines.*
import kotlinx.coroutines.channels.*
import kotlinx.coroutines.sync.*
import java.util.concurrent.ConcurrentHashMap
import java.time.Duration

data class Subscription(val pattern: String, val sessionId: String)

class PatternMatcher {
    // Matches patterns like "sensor.*.temperature.#" against topics
    // '*' matches exactly one segment, '#' matches zero or more segments
    fun matches(pattern: String, topic: String): Boolean {
        return matchSegments(pattern.split("."), topic.split("."), 0, 0)
    }

    private fun matchSegments(patParts: List<String>, topParts: List<String>, pi: Int, ti: Int): Boolean {
        if (pi == patParts.size && ti == topParts.size) return true
        if (pi == patParts.size) return false

        val patSeg = patParts[pi]

        if (patSeg == "#") {
            // '#' can match zero or more remaining segments
            for (k in ti..topParts.size) {
                if (matchSegments(patParts, topParts, pi + 1, k)) return true
            }
            return false
        }

        if (ti == topParts.size) return false

        if (patSeg == "*" || patSeg == topParts[ti]) {
            return matchSegments(patParts, topParts, pi + 1, ti + 1)
        }

        return false
    }
}

class MessageBroker {
    private val subscriptions = ConcurrentHashMap<String, MutableList<Subscription>>()
    private val matcher = PatternMatcher()
    private val subLock = Mutex()
    private val maxSubscriptionsPerSession = 50
    private val maxPatternLength = 200

    suspend fun subscribe(sessionId: String, pattern: String): Boolean {
        if (pattern.length > maxPatternLength) return false
        if (pattern.isBlank()) return false

        subLock.withLock {
            val sessionSubs = subscriptions.values.flatten().count { it.sessionId == sessionId }
            if (sessionSubs >= maxSubscriptionsPerSession) return false

            val bucket = subscriptions.getOrPut(pattern) { mutableListOf() }
            bucket.add(Subscription(pattern, sessionId))
        }
        return true
    }

    suspend fun unsubscribe(sessionId: String, pattern: String) {
        subLock.withLock {
            subscriptions[pattern]?.removeAll { it.sessionId == sessionId }
        }
    }

    suspend fun publish(topic: String): List<String> {
        val matched = mutableListOf<String>()
        subLock.withLock {
            for ((pattern, subs) in subscriptions) {
                if (matcher.matches(pattern, topic)) {
                    matched.addAll(subs.map { it.sessionId })
                }
            }
        }
        return matched.distinct()
    }

    suspend fun removeSession(sessionId: String) {
        subLock.withLock {
            subscriptions.values.forEach { it.removeAll { sub -> sub.sessionId == sessionId } }
            subscriptions.entries.removeAll { it.value.isEmpty() }
        }
    }
}

fun Application.configureWebSocket() {
    install(WebSockets) {
        pingPeriod = Duration.ofSeconds(15)
        timeout = Duration.ofSeconds(30)
        maxFrameSize = Long.MAX_VALUE
    }

    val broker = MessageBroker()
    val sessions = ConcurrentHashMap<String, WebSocketSession>()
    var sessionCounter = 0L
    val counterLock = Mutex()

    routing {
        webSocket("/pubsub") {
            val sessionId = counterLock.withLock {
                "session-${++sessionCounter}"
            }
            sessions[sessionId] = this

            try {
                for (frame in incoming) {
                    if (frame is Frame.Text) {
                        val text = frame.readText()
                        val parts = text.split(" ", limit = 3)
                        when (parts.getOrNull(0)?.uppercase()) {
                            "SUBSCRIBE" -> {
                                val pattern = parts.getOrNull(1) ?: continue
                                val ok = broker.subscribe(sessionId, pattern)
                                send(Frame.Text(if (ok) "OK SUBSCRIBE $pattern" else "ERR limit reached"))
                            }
                            "UNSUBSCRIBE" -> {
                                val pattern = parts.getOrNull(1) ?: continue
                                broker.unsubscribe(sessionId, pattern)
                                send(Frame.Text("OK UNSUBSCRIBE $pattern"))
                            }
                            "PUBLISH" -> {
                                val topic = parts.getOrNull(1) ?: continue
                                val payload = parts.getOrNull(2) ?: ""
                                val recipients = broker.publish(topic)
                                for (rid in recipients) {
                                    sessions[rid]?.send(Frame.Text("MSG $topic $payload"))
                                }
                                send(Frame.Text("OK PUBLISH $topic ${recipients.size}"))
                            }
                            else -> send(Frame.Text("ERR unknown command"))
                        }
                    }
                }
            } finally {
                sessions.remove(sessionId)
                broker.removeSession(sessionId)
            }
        }
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        configureWebSocket()
    }.start(wait = true)
}
